-- PT118-S4-Q2. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT118-S4-Q2$batch09$ AND q.stimulus=$batch09$A factory spokesperson argued that the factory should not be required to clean up the water in the nearby wetlands, maintaining that although wastewater from the factory polluted the wetlands over the past several years, the factory is not to blame for this, since the disposal of the factory’s wastewater is handled entirely by an independent contractor.$batch09$ AND q.prompt=$batch09$Which one of the following arguments most closely conforms to the principle underlying the reasoning in the spokesperson's argument?$batch09$ AND q.correct_choice=$batch09$B$batch09$) THEN RAISE EXCEPTION 'Question changed: PT118-S4-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT118-S4-Q2$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT118-S4-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT118-S4-Q2$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$The factory shouldn't be required to clean up the wetlands.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$The factory's wastewater polluted the wetlands, but an independent contractor handles all the disposal.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The factory admits its wastewater caused the pollution. Its defense is that someone else, acting independently, made the decisions about disposal. The principle: you aren't responsible for harm when an independent party made the choices that caused it.$batch09$), (3, $batch09$Goal$batch09$, $batch09$Someone shouldn't be held responsible for what a separate, independent agent freely did.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT118-S4-Q2$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$This concludes that parents should check teachers' qualifications. Nobody is trying to avoid responsibility.$batch09$), ($batch09$B$batch09$, $batch09$Parents shouldn't answer for older adolescents, because those adolescents have minds of their own and freely choose what to do. That's the factory's defense: we didn't make the choice, an independent party did.$batch09$), ($batch09$C$batch09$, $batch09$This is the trap, picked by 8%. It objects to a burden, as the factory does. But the students' reason is that the material wasn't covered in class. No independent party made the choice. The structure that matters, blaming someone else's free choice, isn't there.$batch09$), ($batch09$D$batch09$, $batch09$The appointee is excluded for a conflict of interest. That's about bias, not shifting responsibility.$batch09$), ($batch09$E$batch09$, $batch09$This doubts a claim based on witnesses' reports. Nobody's responsibility is being shifted.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT118-S4-Q2$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
